#!/usr/bin/env python3
"""md/md-build-run — auto-generated run.py (archetype=generic).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "generic"
BRAIN = "md"
SKILL = "md-build-run"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'ok': True, 'skill_id': 'md-build-run', 'result': {}, 'diagnostics': {'brain': 'Naruto-main', 'archetype': 'generic'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """完整 GROMACS MD pipeline:pdb2gmx → editconf → solvate → ions → grompp → mdrun(short EM)。
    host_env=praxis-md(gmx 2021.3)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pdb = payload.get("input_pdb") or payload.get("protein_pdb")
    ff = payload.get("force_field", "amber99sb-ildn")
    water = payload.get("water_model", "tip3p")
    box_dist = float(payload.get("box_dist_nm", 1.0))
    em_steps = int(payload.get("em_steps", 5000))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="md_build_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "ff": ff, "water": water, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "result": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not pdb or not _os.path.isfile(pdb):
        return {"ok": False, "error": "需要 input_pdb", "diagnostics": diagnostics}
    _os.makedirs(out_dir, exist_ok=True)
    base = _os.path.join(out_dir, "system")
    t0 = _time.time()
    steps = {}
    # 1) pdb2gmx
    r1 = run_tool(["gmx", "pdb2gmx", "-f", pdb, "-o", base + ".gro", "-p", base + ".top",
                   "-ff", ff, "-water", water, "-ignh"], timeout=300)
    steps["pdb2gmx"] = r1.get("returncode")
    if not r1["ok"]:
        return {"ok": False, "error": "pdb2gmx 失败", "stderr": r1.get("stderr", "")[-300:],
                "diagnostics": {**diagnostics, "steps": steps}}
    # 2) editconf
    r2 = run_tool(["gmx", "editconf", "-f", base + ".gro", "-o", base + "_box.gro",
                   "-bt", "cubic", "-d", str(box_dist)], timeout=120)
    steps["editconf"] = r2.get("returncode")
    if not r2["ok"]:
        return {"ok": False, "error": "editconf 失败", "diagnostics": {**diagnostics, "steps": steps}}
    # 3) solvate
    r3 = run_tool(["gmx", "solvate", "-cp", base + "_box.gro", "-cs", "spc216.gro",
                   "-p", base + ".top", "-o", base + "_solv.gro"], timeout=300)
    steps["solvate"] = r3.get("returncode")
    if not r3["ok"]:
        return {"ok": False, "error": "solvate 失败", "diagnostics": {**diagnostics, "steps": steps}}
    # 4) ions (simple EM mdp)
    em_mdp = _os.path.join(out_dir, "em.mdp")
    with open(em_mdp, "w") as fh:
        fh.write(f"integrator = steep\nnsteps = {em_steps}\nemtol = 1000.0\nemstep = 0.01\n"
                 f"nstlist = 10\ncutoff-scheme = Verlet\nrlist = 1.0\nrvdw = 1.0\nrcoulomb = 1.0\n")
    r4 = run_tool(["gmx", "grompp", "-f", em_mdp, "-c", base + "_solv.gro",
                   "-p", base + ".top", "-o", base + "_em.tpr", "-maxwarn", "2"], timeout=120)
    steps["grompp_em"] = r4.get("returncode")
    if not r4["ok"]:
        return {"ok": False, "error": "grompp 失败", "stderr": r4.get("stderr", "")[-300:],
                "diagnostics": {**diagnostics, "steps": steps}}
    # 5) mdrun EM
    r5 = run_tool(["gmx", "mdrun", "-deffnm", base + "_em", "-v"],
                  timeout=int(payload.get("timeout_s", 3600)))
    steps["mdrun_em"] = r5.get("returncode")
    if not r5["ok"]:
        return {"ok": False, "error": "mdrun EM 失败", "stderr": r5.get("stderr", "")[-300:],
                "diagnostics": {**diagnostics, "steps": steps}}
    final_gro = base + "_em.gro"
    return {"ok": True, "skill_id": SKILL,
            "result": "EM done",
            "final_structure": final_gro,
            "topology": base + ".top",
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "steps": steps}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
